import { expect, expectStatus, test, uniqueName, type Vendor } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("search ignores case and matches part of a name", { tag: "@LIF-13" }, async ({ apiAs, factory }) => {
    // Arrange
    const name = uniqueName("Zephyrine Cold Storage");
    const vendor = await factory.vendor({ as: "member", name });
    const member = await apiAs("member");

    // Act
    const response = await member.get("/api/vendors", { params: { q: "COLD stor", limit: 100 } });

    // Assert
    const page = await expectStatus<{ items: Vendor[]; total: number }>(response, 200);
    expect(page.items.map((v) => v.id)).toContain(vendor.id);
  });
});
